effect.shader:
void main(){
  vec2 uv = acScreenNorm;
  float ar = acScreenSize.x / max(acScreenSize.y, 1.0);
  vec2 grid = vec2(blocks * ar, blocks) / max(ar, 1.0);
  vec2 cell = floor(uv * grid) / grid + 0.5 / grid;
  vec4 src = texture2DCv(inputImg.texture, cell);
  float a = max(src.a, 1e-4);
  vec3 c = src.rgb / a;
  float l = gmLum(c);
  float n = max(levels, 2.0) - 1.0;
  float h = floor(l * n + 0.5) / n;
  float lx = gmLum(texture2DCv(inputImg.texture, cell + vec2(1.0 / grid.x, 0.0)).rgb) - l;
  float ly = gmLum(texture2DCv(inputImg.texture, cell + vec2(0.0, 1.0 / grid.y)).rgb) - l;
  float rad = radians(lightAngle);
  float lam = clamp((lx * cos(rad) + ly * sin(rad)) * 6.0 + ambient + h * 0.5, 0.0, 1.4);
  vec3 col = c * lam;
  col = mix(c, col, mixAmt);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0) * a, a);
}
